class Solution {
public:
    int minRotations(string s) {
        int sum = 0;
        int curr = 0;

        for( int i = 0 ;i<s.size();i++){
            int in = s[i]-'0';
            int diff = abs(curr - in);
            sum += min(diff,10-diff);

            curr = in;
        }

        return sum ;
    }
};

class Solution {
public:
    bool checkValidString(string s) {
        int low = 0, high = 0;
        for (char c : s) {
            if (c == '(') {
                low++;
                high++;
            } else if (c == ')') {
                low--;
                high--;
            } else {
                low--;
                high++;
            }
            if (high < 0) return false;
            if (low < 0) low = 0;
        }
        return low == 0;
    }
};
